positional:
var sc = SugarCube;
var v = sc.State.variables;
v.game_state.time_state.current_hour = 7;
v.game_state.time_state.current_minute = 0;
v.game_state.time_state.current_day = 'Wednesday';
v.player.core_traits.corruption = 30;
v.game_state.random_cooldowns = {};
v.game_state.activity_trigger_history = {};
return 'state_set';

var sc = SugarCube;
var setupRef = sc.setup;
// Reset registry cache to force rebuild
setupRef._canvasByIdMap = null;
// Verify all 7 sub canvas targets are now findable
var subs = setupRef.canvasSubstitutions || {};
var resolved = [];
for (var pk in subs) {
  for (var j = 0; j < subs[pk].length; j++) {
    var t = subs[pk][j].target_canvas_id;
    var tCanvas = setupRef.getCanvasById(t);
    resolved.push({target_short: t.slice(0,8), found: !!tCanvas, name: tCanvas ? tCanvas.name : null, sub_only: tCanvas ? tCanvas.substitutionOnly : null});
  }
}
return JSON.stringify({total_sub_targets: resolved.length, all_found: resolved.every(function(r){return r.found;}), resolved: resolved});

var sc = SugarCube;
var setupRef = sc.setup;
var idMap = setupRef._canvasByIdMap || {};
var teaId = null, washId = null;
for (var k in idMap) {
  var n = idMap[k].name || '';
  if (n.indexOf('Make a cup of tea') >= 0 && !idMap[k].substitutionOnly) teaId = k;
  if (n.indexOf('Wash the dishes') >= 0 && !idMap[k].substitutionOnly) washId = k;
}
function rollHarness(parentId, n) {
  var hits = 0, misses = 0, hitTargets = {};
  for (var i = 0; i < n; i++) {
    var sub = setupRef.checkAndSubstituteCanvas(parentId);
    if (sub) {
      hits++;
      hitTargets[sub] = (hitTargets[sub] || 0) + 1;
    } else misses++;
  }
  return {hits: hits, misses: misses, hit_targets: hitTargets};
}
return JSON.stringify({
  tea_id: teaId,
  wash_id: washId,
  tea_20_rolls: rollHarness(teaId, 20),
  wash_20_rolls: rollHarness(washId, 20),
  tea_100_rolls: rollHarness(teaId, 100)
});
